<script>
const catalog=@json($catalog),models={'Lelaki Pendek':{sleeve:'short',label:'Lengan pendek',image:@json(asset('images/jersey/model-pria-pendek-v2.jpg'))},'Lelaki Panjang':{sleeve:'long',label:'Lengan panjang',image:@json(asset('images/jersey/model-pria-panjang-v3.jpg'))},'Muslimah':{sleeve:'long',label:'Lengan panjang',image:@json(asset('images/jersey/model-muslimah-v3.jpg'))}},money=v=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(v);let selectedModel='Lelaki Pendek',selectedSize;
const product=document.getElementById('product'),quantity=document.getElementById('quantity');
const modelNames=Object.keys(models);function renderModels(){const active=modelNames.indexOf(selectedModel),m=models[selectedModel];document.getElementById('preview').src=m.image;document.getElementById('preview').alt=`Jersey ${selectedModel}`;document.getElementById('slider-model').textContent=selectedModel;document.getElementById('model-dots').innerHTML=modelNames.map((name,index)=>`<button type="button" data-model-index="${index}" aria-label="Pilih ${name}" class="h-2.5 rounded-full transition-all ${index===active?'w-8 bg-amber-400':'w-2.5 bg-white/60'}"></button>`).join('');document.querySelectorAll('[data-model-index]').forEach(button=>button.onclick=()=>{selectedModel=modelNames[Number(button.dataset.modelIndex)];renderModels();update()})}function moveModel(delta){const index=(modelNames.indexOf(selectedModel)+delta+modelNames.length)%modelNames.length;selectedModel=modelNames[index];renderModels();update()}
function renderProducts(){product.value=catalog[0].id;renderSizes()}
function currentProduct(){return catalog.find(p=>String(p.id)===product.value)||catalog[0]}
function renderSizes(){const p=currentProduct(),selectedId=selectedSize?.id??selectedSize;selectedSize=p.sizes.find(s=>String(s.id)===String(selectedId))||p.sizes[0];document.getElementById('size-options').innerHTML=p.sizes.map(s=>`<button type="button" data-size="${s.id}" aria-pressed="${s.id===selectedSize.id}" class="rounded-xl border px-4 py-2.5 text-sm font-black ${s.id===selectedSize.id?'border-emerald-700 bg-emerald-50 text-emerald-800':'border-slate-200'}">${s.name}</button>`).join('');document.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{selectedSize=p.sizes.find(s=>String(s.id)===b.dataset.size);renderSizes()});update()}
function updateStock(){const stock=selectedSize.stock,bar=document.getElementById('stock-bar'),label=document.getElementById('stock-label'),count=document.getElementById('stock-count');bar.classList.remove('bg-emerald-500','bg-amber-400','bg-red-500');if(stock===null){label.textContent='Stok tersedia';count.textContent='Tersedia';bar.style.width='100%';bar.classList.add('bg-emerald-500')}else if(stock===0){label.textContent='Stok habis';count.textContent='0 tersedia';bar.style.width='5%';bar.classList.add('bg-red-500')}else if(stock<=5){label.textContent='Stok hampir habis';count.textContent=`${stock} tersisa`;bar.style.width=`${Math.max(15,stock*12)}%`;bar.classList.add('bg-amber-400')}else{label.textContent='Stok tersedia';count.textContent=`${stock} tersedia`;bar.style.width=`${Math.min(100,40+stock*3)}%`;bar.classList.add('bg-emerald-500')}document.getElementById('buy-button').disabled=stock===0;document.getElementById('save-button').disabled=stock===0}
function update(){const p=currentProduct(),m=models[selectedModel],limit=selectedSize.stock===null?20:Math.min(20,Math.max(1,selectedSize.stock)),count=Math.max(1,Math.min(limit,Number(quantity.value)||1));quantity.max=limit;quantity.value=count;document.getElementById('model').value=selectedModel;document.getElementById('sleeve').value=m.sleeve;document.getElementById('size').value=selectedSize.id;document.getElementById('variant').textContent=`${m.label} · Ukuran ${selectedSize.name}`;document.getElementById('subtotal').textContent=money((p.price+Number(selectedSize.adjustment))*count);document.getElementById('summary-model').textContent=selectedModel;document.getElementById('summary-detail').textContent=`Ukuran ${selectedSize.name} · ${count} buah`;updateStock()}
function flyToCart(button){const source=document.getElementById('preview'),target=document.getElementById('cart-button'),start=button.getBoundingClientRect(),end=target.getBoundingClientRect(),size=84,startX=start.left+start.width/2-size/2,startY=Math.max(12,start.top-size-10),endX=end.left+end.width/2-12,endY=end.top+end.height/2-12,clone=source.cloneNode();Object.assign(clone.style,{position:'fixed',zIndex:60,left:`${startX}px`,top:`${startY}px`,width:`${size}px`,height:`${size}px`,border:'3px solid white',boxShadow:'0 12px 30px rgba(0,0,0,.28)',borderRadius:'1rem',objectFit:'cover',pointerEvents:'none'});document.body.appendChild(clone);const curveX=(startX+endX)/2-50,curveY=Math.max(16,Math.min(startY,endY)-90),animation=clone.animate([{left:`${startX}px`,top:`${startY}px`,width:`${size}px`,height:`${size}px`,transform:'rotate(0deg)',opacity:1},{left:`${curveX}px`,top:`${curveY}px`,width:'58px',height:'58px',transform:'rotate(-10deg)',opacity:.9,offset:.55},{left:`${endX}px`,top:`${endY}px`,width:'24px',height:'24px',transform:'rotate(8deg)',opacity:.15}],{duration:850,easing:'cubic-bezier(.22,.7,.24,1)',fill:'forwards'});animation.onfinish=()=>{clone.remove();target.animate([{transform:'scale(1)'},{transform:'scale(1.22)'},{transform:'scale(1)'}],{duration:380,easing:'ease-out'})}}
const form=document.getElementById('selection-form');form.addEventListener('submit',async event=>{if(event.submitter?.value!=='save_cart')return;event.preventDefault();const button=event.submitter,original=button.textContent;button.disabled=true;button.textContent='Menyimpan…';try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}}),data=await response.json();if(!response.ok)throw new Error(data.message||'Gagal menyimpan jersey.');document.getElementById('cart-count').textContent=data.cart_count;document.getElementById('cart-button').setAttribute('aria-label',`Buka keranjang, ${data.cart_count} item`);flyToCart(button)}catch(error){alert(error.message)}finally{button.disabled=false;button.textContent=original}});
quantity.onchange=update;document.getElementById('minus').onclick=()=>{quantity.value=Math.max(1,Number(quantity.value)-1);update()};document.getElementById('plus').onclick=()=>{quantity.value=Math.min(20,Number(quantity.value)+1);update()};document.getElementById('model-prev').onclick=()=>moveModel(-1);document.getElementById('model-next').onclick=()=>moveModel(1);let touchStart=0;const slider=document.getElementById('model-slider');slider.addEventListener('touchstart',event=>touchStart=event.changedTouches[0].clientX,{passive:true});slider.addEventListener('touchend',event=>{const distance=event.changedTouches[0].clientX-touchStart;if(Math.abs(distance)>45)moveModel(distance<0?1:-1)},{passive:true});renderModels();renderProducts();
</script>
